  <a class="skip-link" href="#main">Skip to main content</a>

  <main id="main">
    <section class="page" aria-labelledby="page-title">
      <header class="hero">
        <h1 id="page-title">Image Preview</h1>
        <p class="subtitle">Review the image before removing it from your library.</p>
      </header>

      <article class="preview-card" aria-labelledby="image-title">
        <div class="image-frame">
          <img
            src="https://images.unsplash.com/photo-1516321318423-f06f85e504b3?auto=format&fit=crop&w=1400&q=80"
            alt="A dark workspace with a laptop, notebook, and warm desk lamp lighting"
          >
        </div>

        <div class="card-footer">
          <div class="meta">
            <strong id="image-title">Workspace moodboard</strong>
            <span>Added to your library 2 days ago</span>
          </div>

          <button class="trigger" type="button" aria-haspopup="dialog" aria-controls="delete-dialog">
            Delete image
          </button>
        </div>
      </article>

      <p class="status" id="status" aria-live="polite"></p>
    </section>
  </main>

  <dialog id="delete-dialog" aria-labelledby="dialog-title" aria-describedby="dialog-description">
    <div class="dialog-content">
      <div class="dialog-icon" aria-hidden="true">!</div>
      <div class="dialog-copy">
        <h2 id="dialog-title">Delete this image?</h2>
        <p id="dialog-description">This removes the image from your library. This action cannot be undone.</p>
      </div>
      <form class="dialog-actions" method="dialog">
        <button class="secondary" type="submit" value="cancel">Cancel</button>
        <button class="secondary danger" type="submit" value="delete">Delete</button>
      </form>
    </div>
  </dialog>

  <script>
    const trigger = document.querySelector('.trigger');
    const dialog = document.getElementById('delete-dialog');
    const status = document.getElementById('status');
    const preview = document.querySelector('.preview-card');
    const imageTitle = document.getElementById('image-title');

    let lastFocused = null;

    trigger.addEventListener('click', () => {
      lastFocused = document.activeElement;
      dialog.showModal();
    });

    dialog.addEventListener('close', () => {
      if (dialog.returnValue === 'delete') {
        preview.innerHTML = `
          <div class="dialog-copy">
            <h2 id="image-title">Workspace moodboard removed</h2>
            <p>There is no image left to preview.</p>
          </div>
        `;
        status.textContent = 'Image deleted from your library.';
      }

      if (lastFocused && typeof lastFocused.focus === 'function') {
        lastFocused.focus();
      }
    });

    dialog.addEventListener('cancel', () => {
      lastFocused = trigger;
    });
  </script>
