      border-radius: 1rem;
      overflow: hidden;
      background: var(--panel-2);
      border: 1px solid var(--border);
    }

    .image-frame img {
      display: block;
      width: 100%;
      height: auto;
      aspect-ratio: 16 / 10;
      object-fit: cover;
    }

    .card-footer {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 1rem;
      flex-wrap: wrap;
    }

    .meta {
      display: grid;
      gap: 0.15rem;
    }

    .meta strong {
      font-size: 1rem;
    }

    .meta span {
      color: var(--muted);
      font-size: 0.95rem;
    }

    .trigger,
    .secondary {
      border: 1px solid transparent;
      border-radius: 999px;
      padding: 0.8rem 1.1rem;
      font: inherit;
      font-weight: 650;
      cursor: pointer;
      transition: transform 0.16s ease, background-color 0.16s ease, border-color 0.16s ease;
    }

    .trigger {
      background: linear-gradient(135deg, var(--danger), #ff8d68);
