      border-radius: 1.5rem;
      background: linear-gradient(180deg, #11182b, #0d1324);
      color: var(--text);
      box-shadow: var(--shadow);
    }

    dialog::backdrop {
      background: rgba(5, 8, 22, 0.78);
      backdrop-filter: blur(6px);
    }

    .dialog-content {
      display: grid;
      gap: 1rem;
      padding: 1.5rem;
    }

    .dialog-icon {
      width: 3rem;
      height: 3rem;
