    }

    .dialog-copy p {
      margin: 0;
      color: var(--muted);
    }

    .dialog-actions {
      display: flex;
      justify-content: flex-end;
      gap: 0.75rem;
      flex-wrap: wrap;
    }

    .danger {
      background: linear-gradient(135deg, #ff5e73, #ff7b4d);
      color: #21070a;
      border-color: transparent;
    }

    .hidden {
      display: none;
    }

    @media (max-width: 40rem) {
      main {
        padding-top: 4.25rem;
      }

      .card-footer,
      .dialog-actions {
        align-items: stretch;
      }

      .trigger,
      .secondary {
        width: 100%;
      }
    }

    @media (forced-colors: active) {
      :root {
        --bg: Canvas;
        --panel: Canvas;
